<?php
require dirname(__DIR__).'/db.php'; admin_required();
$notice='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 csrf_check();
 try {
  if(isset($_POST['save_tracks'])) { foreach($_POST['track']??[] as $id=>$row){$title=trim((string)($row['title']??''));$order=(int)($row['sort_order']??0);if($title==='')continue;$q=$pdo->prepare('UPDATE music_tracks SET title=?,enabled=?,sort_order=? WHERE id=?');$q->execute([mb_substr($title,0,150),isset($row['enabled'])?1:0,max(-1000,min(1000,$order)),(int)$id]);} $notice='Configuración de música guardada.'; }
  elseif(isset($_POST['add_card'])) { $cat=$_POST['category']??'';$int=$_POST['intensity']??'';$txt=trim((string)($_POST['card_text']??''));if(!in_array($cat,['verdad','reto','castigo'],true)||!in_array($int,['suave','picante','pesada'],true)||mb_strlen($txt)<4||mb_strlen($txt)>1000)throw new RuntimeException('Revisa categoría, intensidad y texto (4 a 1000 caracteres).');$q=$pdo->prepare('INSERT INTO custom_cards(category,intensity,card_text) VALUES(?,?,?)');$q->execute([$cat,$int,$txt]);$notice='Carta guardada en la base de datos.'; }
  elseif(isset($_POST['card_action'])) { $id=(int)($_POST['card_id']??0);$act=$_POST['card_action'];if($act==='toggle')$pdo->prepare('UPDATE custom_cards SET enabled=1-enabled WHERE id=?')->execute([$id]);elseif($act==='delete')$pdo->prepare('DELETE FROM custom_cards WHERE id=?')->execute([$id]);$notice=$act==='delete'?'Carta eliminada.':'Estado de la carta actualizado.'; }
  elseif(isset($_POST['save_settings'])) { foreach(['maintenance_mode','allow_custom_cards'] as $key){$val=isset($_POST[$key])?'1':'0';$pdo->prepare('INSERT INTO app_settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)')->execute([$key,$val]);}$notice='Ajustes del sistema guardados.'; }
 } catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'No se pudo guardar. Verifica la base de datos.';error_log('Parche Rolo admin: '.$e->getMessage());}
}
$tracks=$pdo->query('SELECT * FROM music_tracks ORDER BY sort_order,id')->fetchAll();
$events=$pdo->query('SELECT id,event_type,payload,created_at FROM game_sessions ORDER BY id DESC LIMIT 25')->fetchAll();
$cards=$pdo->query('SELECT * FROM custom_cards ORDER BY id DESC LIMIT 100')->fetchAll();
$stats=['events'=>(int)$pdo->query('SELECT COUNT(*) FROM game_sessions')->fetchColumn(),'sessions'=>(int)$pdo->query("SELECT COUNT(DISTINCT session_token) FROM game_sessions")->fetchColumn(),'cards'=>(int)$pdo->query('SELECT COUNT(*) FROM custom_cards WHERE enabled=1')->fetchColumn(),'tracks'=>(int)$pdo->query('SELECT COUNT(*) FROM music_tracks WHERE enabled=1')->fetchColumn()];
$settings=[];foreach($pdo->query('SELECT setting_key,setting_value FROM app_settings') as $s)$settings[$s['setting_key']]=$s['setting_value'];
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Panel de administración · Parché Rolo</title><link rel="stylesheet" href="admin.css"></head><body><div class="shell"><header class="top"><div><div class="brand">♛ PARCHÉ <span>ROLO</span> <span class="pill">ADMIN</span></div><div class="sub">Bienvenido, <?=h($_SESSION['admin_name'])?> · Control central de la aplicación</div></div><div class="actions"><a class="btn" href="../index.html">↗ Abrir juego</a><a class="btn primary" href="logout.php">Cerrar sesión ↗</a></div></header>
<?php if($notice):?><div class="notice"><?=h($notice)?></div><?php endif;?><?php if($error):?><div class="notice error"><?=h($error)?></div><?php endif;?>
<section class="grid"><article class="stat" style="--glow:#00f0b5"><div class="label">Eventos registrados</div><div class="number"><?=number_format($stats['events'])?></div><div class="note">Actividad guardada en MySQL</div></article><article class="stat" style="--glow:#00c8ff"><div class="label">Sesiones de juego</div><div class="number"><?=number_format($stats['sessions'])?></div><div class="note">Identificadores de sesión únicos</div></article><article class="stat" style="--glow:#ffbd35"><div class="label">Cartas personalizadas activas</div><div class="number"><?=number_format($stats['cards'])?></div><div class="note">Administrables desde este panel</div></article><article class="stat" style="--glow:#ff27dc"><div class="label">Canciones habilitadas</div><div class="number"><?=number_format($stats['tracks'])?></div><div class="note">Disponibles en el juego</div></article></section>
<div class="split"><section class="panel"><div class="panel-head"><h2>🎵 Música del juego</h2><span class="pill green">MySQL sincronizado</span></div><p>Activa o desactiva canciones, cambia el nombre visible y organiza el orden. Los archivos de audio deben existir en la carpeta principal.</p><form method="post"><input type="hidden" name="csrf_token" value="<?=h(csrf_token())?>"><input type="hidden" name="save_tracks" value="1"><?php foreach($tracks as $t):?><div class="track"><div><label for="track<?=$t['id']?>">Nombre de la canción</label><input class="field" id="track<?=$t['id']?>" name="track[<?=$t['id']?>][title]" value="<?=h($t['title'])?>" maxlength="150"><div class="sub" style="font-size:10px;margin-top:5px"><?=h($t['filename'])?></div></div><div><label>Orden</label><input type="number" name="track[<?=$t['id']?>][sort_order]" value="<?=$t['sort_order']?>" min="-1000" max="1000"></div><label class="toggle"><input type="checkbox" name="track[<?=$t['id']?>][enabled]" <?=$t['enabled']?'checked':''?>> Disponible</label></div><?php endforeach;?><button class="btn primary" type="submit">Guardar canciones</button></form></section>
<section class="panel"><div class="panel-head"><h2>🃏 Crear carta personalizada</h2><span class="pill">Nueva</span></div><p>Las cartas quedan almacenadas en la base de datos y puedes habilitarlas o eliminarlas abajo.</p><form method="post"><input type="hidden" name="csrf_token" value="<?=h(csrf_token())?>"><input type="hidden" name="add_card" value="1"><div class="formrow"><div><label>Categoría</label><select name="category"><option value="verdad">Verdad</option><option value="reto">Reto</option><option value="castigo">Castigo</option></select></div><div><label>Intensidad</label><select name="intensity"><option value="suave">Suave</option><option value="picante" selected>Picante</option><option value="pesada">Pesada</option></select></div></div><label>Texto de la carta</label><textarea name="card_text" rows="5" maxlength="1000" required placeholder="Escribe la pregunta o el reto..."></textarea><button class="btn primary" type="submit" style="margin-top:12px">＋ Guardar carta</button></form><hr style="border-color:#28345d;margin:22px 0"><h2>⚙️ Ajustes del sistema</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=h(csrf_token())?>"><input type="hidden" name="save_settings" value="1"><label class="toggle"><input type="checkbox" name="allow_custom_cards" value="1" <?=($settings['allow_custom_cards']??'1')==='1'?'checked':''?>> Permitir cartas personalizadas</label><label class="toggle"><input type="checkbox" name="maintenance_mode" value="1" <?=($settings['maintenance_mode']??'0')==='1'?'checked':''?>> Modo mantenimiento (solo guarda preferencia)</label><p style="font-size:11px">Nota: el modo mantenimiento se guarda en MySQL, pero no bloquea automáticamente el juego.</p><button class="btn" type="submit">Guardar ajustes</button></form></section></div>
<section class="panel"><div class="panel-head"><h2>🗂️ Cartas personalizadas</h2><span class="pill"><?=count($cards)?> últimas (máx. 100)</span></div><?php if(!$cards):?><div class="empty">Todavía no hay cartas personalizadas.</div><?php else:?><div class="table-wrap"><table><thead><tr><th>ID</th><th>Tipo / intensidad</th><th>Contenido</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach($cards as $c):?><tr><td>#<?=$c['id']?></td><td><?=h($c['category'])?><br><span class="sub"><?=h($c['intensity'])?></span></td><td><?=h($c['card_text'])?></td><td><span class="pill <?=$c['enabled']?'green':'off'?>"><?=$c['enabled']?'Activa':'Desactivada'?></span></td><td><form method="post" style="display:flex;gap:6px;flex-wrap:wrap"><input type="hidden" name="csrf_token" value="<?=h(csrf_token())?>"><input type="hidden" name="card_id" value="<?=$c['id']?>"><button class="btn" name="card_action" value="toggle" type="submit"><?=$c['enabled']?'Desactivar':'Activar'?></button><button class="btn" name="card_action" value="delete" type="submit" onclick="return confirm('¿Eliminar esta carta permanentemente?')">Eliminar</button></form></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<section class="panel"><div class="panel-head"><h2>📡 Actividad reciente</h2><span class="pill">Últimos 25 eventos</span></div><?php if(!$events):?><div class="empty">Aún no hay eventos registrados. Juega una partida para comenzar a ver actividad.</div><?php else:?><div class="table-wrap"><table><thead><tr><th>Evento</th><th>Fecha</th><th>Datos recibidos</th></tr></thead><tbody><?php foreach($events as $e):?><tr><td>#<?=$e['id']?> · <?=h($e['event_type'])?></td><td><?=h($e['created_at'])?></td><td><details><summary>Ver datos</summary><pre style="white-space:pre-wrap;max-width:560px;overflow:auto"><?=h($e['payload'])?></pre></details></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><footer class="foot">PARCHÉ ROLO · Creador: keromato · Panel protegido</footer></div></body></html>
